def priority(task, state, m=10.0, c=2.0, boost=1e6, alpha=0.25, b=1.0, w=0.0,
             fmap=1.0, freduce=1.0, fjoin=1.0, fother=1.0):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0

    if task.task_type == 'map':
        type_factor = fmap
    elif task.task_type == 'reduce':
        type_factor = freduce
    elif task.task_type == 'join':
        type_factor = fjoin
    else:
        type_factor = fother

    weight = max(task.weight, 1e-6) ** w
    base = tier * type_factor * weight / (est * (need ** alpha))
    excess = wait - c * est
    if excess > 0.0:
        return boost + b * excess / est + base
    return base

