def priority(task, state, c=2.0, k=1.0, a=1.0, alpha=0.0, b=0.1):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = c * est - wait
    base = a / max(est * (cores ** alpha), 1e-6)
    if slack <= 0.0:
        return 1e12 + base * (1.0 + (-slack) / est)
    norm_slack = max(slack, 1e-6) / est
    return base * (b + k / max(norm_slack, 1e-6))

