def priority(task, state, c=2.0, g=1e6, eps=1e-6, m=1.0, w=1.0, p=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = c * est - wait
    tier = m if task.tenant == 'premium' else 1.0
    wt = max(task.weight, 1e-6) ** w
    guard = g if slack <= 0.0 else 0.0
    if slack > 0.0:
        base = tier * wt / (max(slack, eps) ** p)
    else:
        base = tier * wt / est
    return float(guard + base)

