def priority(task, state, c=2.0, alpha=1.0, p=1.0, m=1.0, rho=0.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if ratio >= c:
        hard = 1e6
    else:
        hard = 0.0
    late = max(0.0, ratio - c)
    if late > 1e-12:
        late_pow = late ** p
        if late_pow > 1e50:
            late_pow = 1e50
    else:
        late_pow = 0.0
    soft = 1.0 + alpha * late_pow
    tier = m if task.tenant == 'premium' else 1.0
    res = 1.0 / (max(task.resource_need, 1e-6) ** rho)
    return hard + tier * res * soft / est

def priority(task, state, c=2.0, m=1.0, w=0.0, map_mult=1.0, reduce_mult=1.0, join_mult=1.0, fit_boost=0.0, rho=0.0, a=0.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if ratio >= c:
        hard = 1e6 + a * (ratio - c)
    else:
        hard = 0.0
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        tmult = map_mult
    elif task.task_type == 'reduce':
        tmult = reduce_mult
    elif task.task_type == 'join':
        tmult = join_mult
    else:
        tmult = 1.0
    weight_factor = max(1.0 + w * (max(task.weight, 0.0) - 1.0), 0.0)
    fits = 1.0 + fit_boost * (1.0 if task.resource_need <= state.free else 0.0)
    res = 1.0 / (max(task.resource_need, 1e-6) ** rho)
    return hard + tier * tmult * weight_factor * fits * res / est

